/* Global behaviour: header, menus, scroll thread, booking month, year */
(function () {
  document.documentElement.classList.remove('no-js');

  // Local preview: when opened straight from disk (file://), point folder links at their index.html.
  // On a real web server this does nothing, so URLs stay clean for SEO.
  if (window.location.protocol === 'file:') {
    document.querySelectorAll('a[href]').forEach(function (a) {
      var href = a.getAttribute('href');
      if (/^(https?:|mailto:|tel:|#)/.test(href)) return;
      if (href === './' || href === '' ) { a.setAttribute('href', 'index.html'); return; }
      if (href.slice(-1) === '/') a.setAttribute('href', href + 'index.html');
    });
    var form = document.querySelector('[data-quote-form]');
    if (form && form.getAttribute('action').slice(-1) === '/') form.setAttribute('action', form.getAttribute('action') + 'index.html');
  }

  var header = document.querySelector('.site-header');
  var lastY = window.scrollY;
  var thread = document.querySelector('.scroll-thread span');

  function onScroll() {
    var y = window.scrollY;
    if (header) {
      header.classList.toggle('is-scrolled', y > 20);
      // hide on scroll down, show on scroll up (not while mobile menu is open)
      var menuOpen = document.body.classList.contains('menu-open');
      header.classList.toggle('is-hidden', !menuOpen && y > 400 && y > lastY);
    }
    if (thread) {
      var max = document.documentElement.scrollHeight - window.innerHeight;
      thread.style.setProperty('--progress', max > 0 ? (y / max).toFixed(4) : 0);
    }
    lastY = y;
  }
  window.addEventListener('scroll', onScroll, { passive: true });
  onScroll();

  // Mobile menu
  var toggle = document.querySelector('.menu-toggle');
  var sheet = document.getElementById('mobile-menu');
  if (toggle && sheet) {
    toggle.addEventListener('click', function () {
      var open = toggle.getAttribute('aria-expanded') !== 'true';
      toggle.setAttribute('aria-expanded', String(open));
      toggle.setAttribute('aria-label', open ? 'Close menu' : 'Open menu');
      sheet.classList.toggle('is-open', open);
      document.body.classList.toggle('menu-open', open);
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === 'Escape' && sheet.classList.contains('is-open')) toggle.click();
    });
  }

  // Desktop services dropdown: click / keyboard support
  document.querySelectorAll('.nav__item--drop').forEach(function (item) {
    var btn = item.querySelector('button');
    if (!btn) return;
    btn.addEventListener('click', function () {
      var open = !item.classList.contains('is-open');
      item.classList.toggle('is-open', open);
      btn.setAttribute('aria-expanded', String(open));
    });
    item.addEventListener('focusout', function (e) {
      if (!item.contains(e.relatedTarget)) { item.classList.remove('is-open'); btn.setAttribute('aria-expanded', 'false'); }
    });
  });

  // "Now booking projects for <next month>"
  var months = ['January','February','March','April','May','June','July','August','September','October','November','December'];
  var next = months[(new Date().getMonth() + 1) % 12];
  document.querySelectorAll('[data-booking-month]').forEach(function (el) { el.textContent = next; });

  // Footer year
  document.querySelectorAll('[data-year]').forEach(function (el) { el.textContent = new Date().getFullYear(); });
})();
/* Scroll reveals and headline word split (keeps accent spans) */
(function () {
  var reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var i = 0;
  function wrap(word, cls) {
    var w = '<span class="split-word' + (cls ? ' ' + cls : '') + '" style="--i:' + (i++) + '">' + word + '</span>';
    return '<span class="split-line" aria-hidden="true">' + w + '</span>';
  }
  document.querySelectorAll('[data-split]').forEach(function (el) {
    if (reduce) return;
    i = 0;
    el.setAttribute('aria-label', el.textContent.trim().replace(/\s+/g, ' '));
    var out = [];
    el.childNodes.forEach(function (node) {
      var cls = node.nodeType === 1 ? node.className : '';
      node.textContent.split(/\s+/).forEach(function (w) { if (w) out.push(wrap(w, cls)); });
    });
    el.innerHTML = out.join(' ');
  });

  var items = document.querySelectorAll('[data-reveal]');
  if (reduce || !('IntersectionObserver' in window)) {
    items.forEach(function (el) { el.classList.add('is-in'); });
    return;
  }
  var io = new IntersectionObserver(function (entries) {
    entries.forEach(function (entry) {
      if (entry.isIntersecting) { entry.target.classList.add('is-in'); io.unobserve(entry.target); }
    });
  }, { rootMargin: '0px 0px -12% 0px', threshold: 0.08 });
  items.forEach(function (el) { io.observe(el); });

  // Gentle scroll-linked parallax on the hero visual, for a bit of 3D depth.
  var parallax = document.querySelector('.hero__visual');
  if (parallax && !reduce) {
    var ticking = false;
    function update() {
      var rect = parallax.getBoundingClientRect();
      var mid = rect.top + rect.height / 2 - window.innerHeight / 2;
      var shift = Math.max(-30, Math.min(30, mid * -0.08));
      parallax.style.transform = 'translateY(' + shift.toFixed(1) + 'px)';
      ticking = false;
    }
    window.addEventListener('scroll', function () {
      if (!ticking) { requestAnimationFrame(update); ticking = true; }
    }, { passive: true });
    update();
  }
})();
/* Builds an animated woven swatch (warp + weft) inside every [data-weave] */
(function () {
  var NS = 'http://www.w3.org/2000/svg';
  var reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var palettes = {
    hero: { warp: ['#DCCBA8', '#E8DBC0'], weft: ['#D9713F', '#F3C94D', '#B8572B', '#E8936A'] },
    pink: { warp: ['#2B241C', '#453A2C'], weft: ['#D9713F', '#F6D9C4'] },
    peacock: { warp: ['#2B241C', '#453A2C'], weft: ['#B8572B', '#E8936A'] },
    turmeric: { warp: ['#2B241C', '#453A2C'], weft: ['#F3C94D', '#FBE9AE'] }
  };

  function el(name, attrs) {
    var n = document.createElementNS(NS, name);
    for (var k in attrs) n.setAttribute(k, attrs[k]);
    return n;
  }

  document.querySelectorAll('[data-weave]').forEach(function (box) {
    var pal = palettes[box.getAttribute('data-weave')] || palettes.hero;
    var gap = parseInt(box.getAttribute('data-gap') || '34', 10);
    var w = 720, h = 720;
    var cols = Math.ceil(w / gap) + 1, rows = Math.ceil(h / gap) + 1;
    var sw = gap * 0.56;
    var svg = el('svg', { viewBox: '0 0 ' + w + ' ' + h, preserveAspectRatio: 'xMidYMid slice', 'aria-hidden': 'true', focusable: 'false' });
    var gWarp = el('g', {}), gWeft = el('g', {}), gOver = el('g', {});
    var i, j, x, y, d;

    // warp: vertical threads, drawn top to bottom
    for (i = 0; i < cols; i++) {
      x = i * gap + gap / 2;
      d = (i * 0.045).toFixed(3) + 's';
      gWarp.appendChild(el('path', { class: 'warp', d: 'M' + x + ' -10V' + (h + 10), stroke: pal.warp[i % pal.warp.length], 'stroke-width': sw, style: '--len:' + (h + 20) + ';--d:' + d }));
    }
    // weft: horizontal threads, drawn left to right after the warp
    for (j = 0; j < rows; j++) {
      y = j * gap + gap / 2;
      d = (0.6 + j * 0.06).toFixed(3) + 's';
      gWeft.appendChild(el('path', { class: 'weft', d: 'M-10 ' + y + 'H' + (w + 10), stroke: pal.weft[j % pal.weft.length], 'stroke-width': sw, style: '--len:' + (w + 20) + ';--d:' + d }));
    }
    // over-segments: warp passes over weft on alternate crossings, giving the plain-weave look
    for (j = 0; j < rows; j++) {
      for (i = 0; i < cols; i++) {
        if ((i + j) % 2) continue;
        x = i * gap + gap / 2; y = j * gap + gap / 2;
        d = (1.5 + j * 0.06 + i * 0.012).toFixed(3) + 's';
        gOver.appendChild(el('path', { class: 'over', d: 'M' + x + ' ' + (y - gap / 2 + 1) + 'V' + (y + gap / 2 - 1), stroke: pal.warp[i % pal.warp.length], 'stroke-width': sw, style: '--d:' + d }));
      }
    }
    svg.appendChild(gWarp); svg.appendChild(gWeft); svg.appendChild(gOver);
    box.appendChild(svg);
    if (reduce) box.classList.add('weave--static');
  });
})();
/* Fills the process thread as the steps scroll through the viewport */
(function () {
  var lists = document.querySelectorAll('.process');
  if (!lists.length) return;
  function update() {
    lists.forEach(function (list) {
      var r = list.getBoundingClientRect();
      var vh = window.innerHeight;
      var p = Math.min(1, Math.max(0, (vh * 0.75 - r.top) / (r.height + vh * 0.25)));
      var track = list.parentElement.querySelector('.process__track');
      if (track) track.style.setProperty('--p', p.toFixed(3));
      var steps = list.querySelectorAll('li');
      steps.forEach(function (li, i) { li.classList.toggle('is-done', p >= (i + 0.5) / steps.length); });
    });
  }
  window.addEventListener('scroll', update, { passive: true });
  window.addEventListener('resize', update);
  update();
})();
/* Smooth open/close for <details> FAQ items */
(function () {
  var reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  document.querySelectorAll('.faq details').forEach(function (d) {
    var summary = d.querySelector('summary');
    var body = d.querySelector('.faq__body');
    if (!summary || !body || reduce) return;
    summary.addEventListener('click', function (e) {
      e.preventDefault();
      if (d.open) {
        var h = body.scrollHeight;
        body.animate([{ height: h + 'px', opacity: 1 }, { height: '0px', opacity: 0 }], { duration: 350, easing: 'cubic-bezier(.65,0,.35,1)' }).onfinish = function () { d.open = false; };
        d.classList.remove('is-open');
      } else {
        d.open = true;
        var h2 = body.scrollHeight;
        body.animate([{ height: '0px', opacity: 0 }, { height: h2 + 'px', opacity: 1 }], { duration: 420, easing: 'cubic-bezier(.22,.8,.2,1)' });
      }
    });
  });
})();
/* Quote form: validates, then logs the enquiry to a Google Sheet via Apps Script (no server needed) */
(function () {
  var form = document.querySelector('[data-quote-form]');
  if (!form) return;
  var status = form.querySelector('.form__status');
  var sheetUrl = form.getAttribute('data-sheet-url'); // Apps Script Web App URL, see _dev/leads-apps-script.gs

  function isWeakPhone(raw) {
    var core = raw.replace(/\D/g, '').slice(-10);
    if (core.length < 10) return false; // let "required"/pattern handle short input
    if (/^(\d)\1{9}$/.test(core)) return true; // e.g. 9999999999
    var ascending = true, descending = true;
    for (var i = 1; i < core.length; i++) {
      var diff = (Number(core[i]) - Number(core[i - 1]) + 10) % 10; // wraps 9->0 and 0->9
      if (diff !== 1) ascending = false;
      if (diff !== 9) descending = false;
    }
    return ascending || descending; // e.g. 1234567890 or 9876543210
  }

  var phoneInput = form.querySelector('#f-phone');
  if (phoneInput) {
    phoneInput.addEventListener('input', function () {
      phoneInput.setCustomValidity(isWeakPhone(phoneInput.value) ? 'weak' : '');
    });
  }

  function check(field) {
    var input = field.querySelector('input, select, textarea');
    var ok = input.checkValidity();
    field.classList.toggle('is-invalid', !ok);
    input.setAttribute('aria-invalid', String(!ok));
    return ok;
  }
  form.querySelectorAll('.field').forEach(function (f) {
    var input = f.querySelector('input, select, textarea');
    input.addEventListener('blur', function () { if (input.value) check(f); });
  });

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    var fields = form.querySelectorAll('.field');
    var allOk = true, firstBad = null;
    fields.forEach(function (f) { if (!check(f)) { allOk = false; firstBad = firstBad || f; } });
    if (!allOk) { firstBad.querySelector('input, select, textarea').focus(); status.textContent = 'Fill in the highlighted fields to send your enquiry.'; return; }

    var data = new FormData(form);

    // sendBeacon (not fetch) because the page navigates away right after this: fetch
    // requests get cancelled on navigation, sendBeacon is built to survive it.
    if (sheetUrl) {
      try {
        if (navigator.sendBeacon) {
          navigator.sendBeacon(sheetUrl, data);
        } else {
          fetch(sheetUrl, { method: 'POST', mode: 'no-cors', body: new URLSearchParams(data), keepalive: true });
        }
      } catch (err) { /* logging is best-effort; never blocks the enquiry */ }
    }

    status.textContent = 'Sending your enquiry…';
    setTimeout(function () { window.location.href = form.getAttribute('action'); }, 600);
  });
})();
/* Accessible tabs for the pricing page, with a sliding pill */
(function () {
  var tablist = document.querySelector('[role="tablist"]');
  if (!tablist) return;
  var tabs = Array.prototype.slice.call(tablist.querySelectorAll('[role="tab"]'));
  var pill = tablist.querySelector('.tabs__pill');

  function select(tab, focus) {
    tabs.forEach(function (t) {
      var on = t === tab;
      t.setAttribute('aria-selected', String(on));
      t.tabIndex = on ? 0 : -1;
      document.getElementById(t.getAttribute('aria-controls')).hidden = !on;
    });
    if (pill) { pill.style.width = tab.offsetWidth + 'px'; pill.style.transform = 'translateX(' + tab.offsetLeft + 'px)'; }
    if (focus) tab.focus();
    if (history.replaceState) history.replaceState(null, '', '#' + tab.dataset.slug);
  }
  tabs.forEach(function (t, i) {
    t.addEventListener('click', function () { select(t); });
    t.addEventListener('keydown', function (e) {
      if (e.key === 'ArrowRight') select(tabs[(i + 1) % tabs.length], true);
      if (e.key === 'ArrowLeft') select(tabs[(i - 1 + tabs.length) % tabs.length], true);
    });
  });
  var start = tabs.filter(function (t) { return '#' + t.dataset.slug === location.hash; })[0] || tabs[0];
  select(start);
  window.addEventListener('resize', function () { select(tabs.filter(function (t) { return t.getAttribute('aria-selected') === 'true'; })[0]); });
})();
/* Filters case studies by platform on the Work page */
(function () {
  var buttons = document.querySelectorAll('[data-filter]');
  if (!buttons.length) return;
  var rows = document.querySelectorAll('[data-platform]');
  buttons.forEach(function (b) {
    b.addEventListener('click', function () {
      var f = b.getAttribute('data-filter');
      buttons.forEach(function (x) { x.setAttribute('aria-pressed', String(x === b)); });
      rows.forEach(function (r) { r.classList.toggle('is-hidden', f !== 'all' && r.getAttribute('data-platform').indexOf(f) === -1); });
    });
  });
})();
/* Featured-work carousel: pagination dots, autoplay, pauses on hover/focus/off-screen */
(function () {
  var wraps = document.querySelectorAll('.work-carousel-wrap');
  if (!wraps.length) return;
  var reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  wraps.forEach(function (wrap) {
    var track = wrap.querySelector('.work-carousel');
    var dotsBox = wrap.querySelector('[data-work-dots]');
    var cards = Array.prototype.slice.call(track.querySelectorAll('.work-card'));
    if (!track || !cards.length) return;

    function cardLeft(card) {
      return card.getBoundingClientRect().left - track.getBoundingClientRect().left + track.scrollLeft;
    }

    function setActive() {
      var pos = track.scrollLeft;
      var closest = 0;
      var best = Infinity;
      cards.forEach(function (card, i) {
        var d = Math.abs(cardLeft(card) - pos);
        if (d < best) { best = d; closest = i; }
      });
      dots.forEach(function (dot, i) { dot.classList.toggle('is-active', i === closest); });
    }

    function settleActive() {
      setActive();
      clearTimeout(settleActive._t1);
      clearTimeout(settleActive._t2);
      settleActive._t1 = setTimeout(setActive, 350);
      settleActive._t2 = setTimeout(setActive, 650);
    }

    var dots = cards.map(function (card, i) {
      var dot = document.createElement('button');
      dot.type = 'button';
      dot.className = 'work-dots__dot';
      dot.setAttribute('aria-label', 'Go to project ' + (i + 1));
      dot.addEventListener('click', function () {
        track.scrollTo({ left: cardLeft(card), behavior: 'smooth' });
        settleActive();
      });
      if (dotsBox) dotsBox.appendChild(dot);
      return dot;
    });

    setActive();

    var scrollTimer = null;
    track.addEventListener('scroll', function () {
      clearTimeout(scrollTimer);
      scrollTimer = setTimeout(setActive, 80);
    }, { passive: true });

    if (reduceMotion) return;

    var delay = 3500;
    var timer = null;

    function step() {
      var gap = parseFloat(getComputedStyle(track).columnGap) || 0;
      return cards[0].getBoundingClientRect().width + gap;
    }
    function advance() {
      var max = track.scrollWidth - track.clientWidth;
      if (track.scrollLeft >= max - 4) {
        track.scrollTo({ left: 0, behavior: 'smooth' });
      } else {
        track.scrollBy({ left: step(), behavior: 'smooth' });
      }
      settleActive();
    }
    function start() {
      if (timer || track.scrollWidth <= track.clientWidth + 4) return;
      timer = setInterval(advance, delay);
    }
    function stop() {
      if (timer) { clearInterval(timer); timer = null; }
    }

    var io = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting) start(); else stop();
      });
    }, { threshold: .3 });
    io.observe(track);

    ['pointerenter', 'focusin', 'touchstart'].forEach(function (evt) {
      track.addEventListener(evt, stop, { passive: true });
    });
    ['pointerleave', 'focusout'].forEach(function (evt) {
      track.addEventListener(evt, start, { passive: true });
    });
  });
})();
